///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.lodingYn = "N";
scwin.pValue = "";
scwin.pfirstValue = "";
scwin.vCond = "";
scwin.rptHeader = "";
scwin.rex_rptname = ""; // Rexpert리포트 파일명
scwin.gComNm = "";
scwin.gCreatDdtm = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.userParam;
scwin.testDateSet;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex(1);
        await scwin.setCode();
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_ReqSDate.setValue($c.ut.cGetMinusDate2(vCurDate, 14));
        edt_ReqEDate.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.lodingYn = 'Y';
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_ISUR_CD_onselchange
 * @description cmb_ISUR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.cmb_ISUR_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_REPORT_CD_onselchange
 * @description cmb_REPORT_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_REPORT_CD_onselchange = async function() {
    try {
        edt_INVSTG_BILL_DD.setReadOnly(true);
        edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#b9d4f7';
        edt_INVSTG_NOTI_DD.setReadOnly(true);
        edt_INVSTG_NOTI_DD.ReadOnlyBackgroundColor = '#b9d4f7';
        edt_LIST_DD.setReadOnly(true);
        edt_LIST_DD.ReadOnlyBackgroundColor = '#b9d4f7';
        let vReportCd = cmb_REPORT_CD.getValue();
        if (vReportCd === "2") {
            edt_INVSTG_BILL_DD.setReadOnly(false);
            edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
        } else if (vReportCd === "4") {
            edt_INVSTG_BILL_DD.setReadOnly(false);
            edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
            edt_INVSTG_NOTI_DD.setReadOnly(false);
            edt_INVSTG_NOTI_DD.ReadOnlyBackgroundColor = '#ffffff';
        } else if (vReportCd === "5") {
            edt_LIST_DD.setReadOnly(false);
            edt_LIST_DD.ReadOnlyBackgroundColor = '#ffffff';
        }
        if (MaxTab_01.getSelectedTabIndex() === 2 && vReportCd === "1") {
            edt_INVSTG_BILL_DD.setReadOnly(false);
            edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.cmb_REPORT_CD_onselchange" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
        let vReportCd = cmb_REPORT_CD.getValue();
        if (vReportCd === "1") {
            if (MaxTab_01.getSelectedTabIndex() === 2) {
                edt_INVSTG_BILL_DD.setReadOnly(false);
                edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
            } else {
                edt_INVSTG_BILL_DD.setReadOnly(true);
                edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#b9d4f7';
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.MaxTab_01_OnSelChanged" });
    }
};

