/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_ReqSDate, edt_ReqEDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Print_onclick = async function() {
    try {
        let vCheckLmt = 0;
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            for (let i = 1; i <= dts_List_1.getRowCount(); i++) {
                if (dts_List_1.getCellData(i, "CHECK") === "T") {
                    vCheckLmt = vCheckLmt + 1;
                }
            }
            if (vCheckLmt > 1000) {
                await $c.win.alert("인쇄가능 데이터는 1,000건으로 제한 됩니다.(현재 " + vCheckLmt + " 건 선택)");
                return false;
            }
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            for (let i = 1; i <= dts_List_2.getRowCount(); i++) {
                if (dts_List_2.getCellData(i, "CHECK") === "T") {
                    vCheckLmt = vCheckLmt + 1;
                }
            }
            if (vCheckLmt > 1000) {
                await $c.win.alert("인쇄가능 데이터는 1,000건으로 제한 됩니다.(현재 " + vCheckLmt + " 건 선택 )");
                return false;
            }
        }
        $c.stf.doLogSave("ULDSTF05904.xml", SCREN_PROCS_TP_CD_05);
        await scwin.print();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05904.btn_Print_onclick" });
    }
};

/**
 * @method
