    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.gComNm = dts_ComNm.getCellData(1, "COM_NM");
};

/**
 * @method
 * @name readSync
 * @description 인쇄할 내용을 불러온다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&REPORT_KND=" + MaxTab_01.getSelectedTabIndex();
    url += "&REPORT_CD=" + cmb_REPORT_CD.getValue();
    url += "&EMP_NO=" + js_emp_no;
    url += "&DATA_CREAT_DDTM=" + scwin.gCreatDdtm;
    url += "&INVSTG_BILL_DD=" + edt_INVSTG_BILL_DD.getValue();
    url += scwin.vCond;
    const sbmOptions = {
        id : "sbm_dts_Report",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Report=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

