scwin.corpReadSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.pfirstValue;
    url += "&REPORT_KND=" + MaxTab_01.getSelectedTabIndex();
    url += "&REPORT_CD=" + cmb_REPORT_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_CorpReport",
        action : "/ElwListedReceive.do",
        ref : "",
