    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setValueKey
 * @description set Value Key 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setValueKey = async function(dtsObj) {
    scwin.pValue = "";
    scwin.pfirstValue = "";
    let tmpValue = "";
    scwin.sTimer();
    dts_BzProcsNo.removeAll();
    const sbmOptions = {
        id : "sbm_dts_BzProcsNo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_BzProcsNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_BzProcsNo.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            scwin.pfirstValue = dtsObj.getCellData(i, "BZ_PROCS_NO");
            dts_BzProcsNo.insertRow();
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "EMP_NO", js_emp_no);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "DATA_CREAT_DDTM", scwin.gCreatDdtm);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "BZ_PROCS_NO", scwin.pfirstValue);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "WRTRPT_TP_CD", cmb_REPORT_CD.getValue());
            if (tmpValue !== scwin.pfirstValue.substring(0, 8)) {
                tmpValue = scwin.pfirstValue.substring(0, 8);
                if (i === 1) {
                    scwin.pValue = scwin.pfirstValue;
                } else {
                    scwin.pValue = scwin.pfirstValue + "," + scwin.pValue;
                }
            } else {
                scwin.pValue = dtsObj.getCellData(i, "BZ_PROCS_NO").substring(8, 14) + "," + scwin.pValue;
            }
        }
    }
    dts_BzProcsNo.setBroadcast(true, true);
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions3 = {
        id : "sbm_trs_Save",
        action : "/ElwListedReceive.do",
        ref : "dts_BzProcsNo",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
