/**
 * @method
 * @name sTimer
 * @description s Timer 처리
 * @returns {void}
 * @hidden N
 */
scwin.sTimer = function() {
    const clientnow = new Date();
    const curYear = clientnow.getYear();
    const curMonth = (clientnow.getMonth()) + 1;
    const curDay = clientnow.getDate();
    const hours = clientnow.getHours();
    let minutes = clientnow.getMinutes();
    let seconds = clientnow.getSeconds();
    if (minutes <= 9) {
        minutes = "0" + minutes;
    }
    if (seconds <= 9) {
        seconds = "0" + seconds;
    }
    scwin.gCreatDdtm = curYear + "" + curMonth + "" + curDay + "" + hours + "" + minutes + "" + seconds;
    return scwin.gCreatDdtm;
};

/**
