/**
 * @method
 * @name getIsuNmInfo
 * @description get Isu Nm Info 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.getIsuNmInfo = function(dtsObj) {
    const arrPar = new Array();
    for (let i = 1, p = 0; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            arrPar[p] = dtsObj.getCellData(i, "ISU_ABBRV2");
            p++;
        }
    }
    return $c.elw.fn_getArrIsuNmInfo(arrPar);
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    }
    await scwin.setValueKey(dtsObj);
    if (scwin.pValue === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    let vReportCd = cmb_REPORT_CD.getValue();
    await scwin.setComNm(cmb_ISUR_CD.getValue());
    if (vReportCd === "1") {
        let arrIsuStr = scwin.getIsuNmInfo(dtsObj);
        await scwin.print1(arrIsuStr);
    } else if (vReportCd === "2") {
        await scwin.print2();
    } else if (vReportCd === "3") {
        await scwin.print3();
    } else if (vReportCd === "4") {
        let arrIsuStr = scwin.getIsuNmInfo(dtsObj);
        await scwin.print4(arrIsuStr);
    } else if (vReportCd === "5") {
        await scwin.print5();
    }
};

