/**
 * @method
 * @name printOld
 * @description ASIS rexpert-bak 2018-04-03
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printOld = async function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    }
    await scwin.setValueKey(dtsObj);
    if (scwin.pValue === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    let vReportCd = cmb_REPORT_CD.getValue();
    await scwin.setComNm(cmb_ISUR_CD.getValue());
    if (vReportCd === "1") {
        let arrIsuStr = scwin.getIsuNmInfo(dtsObj);
        await scwin.print1Old(arrIsuStr);
    } else if (vReportCd === "2") {
        await scwin.print2Old();
    } else if (vReportCd === "3") {
        await scwin.print3Old();
    } else if (vReportCd === "4") {
        let arrIsuStr = scwin.getIsuNmInfo(dtsObj);
        await scwin.print4Old(arrIsuStr);
    } else if (vReportCd === "5") {
        await scwin.print5Old();
    }
};

